'use client';

import { useEffect } from 'react';
import { usePathname } from 'next/navigation';

const CARD_SELECTOR = [
  '.quick-option',
  '.pillar-card',
  '.aviation-card',
  '.aviation-index-grid > a',
  '.aviation-related-grid > a',
  '.aviation-process-grid > article',
  '.aviation-use-list > li',
  '.global-mosaic > a',
  '.global-related-grid > a',
  '.global-type-grid > article',
  '.global-use-cases > ul > li',
  '.club-inclusion-grid > article',
  '.club-process-grid > *',
  '.franchise-profile-grid > *',
  '.franchise-investment-card',
  '.franchise-support-grid > *',
  '.corporate-sections > article',
  '.destination-results > article',
  '.insight-card',
  '.plan-card',
  '.process-step',
  '.why-item',
].join(',');

const EASE = 'cubic-bezier(0.2, 0.75, 0.3, 1)';

const ENTRANCE_SELECTOR = [
  '.hero-copy > *',
  '.club-hero-copy > *',
  '.aviation-service-hero-copy > *',
  '.global-service-hero-copy > *',
  '.franchise-hero-copy > *',
  '.hero-visual',
  '.club-hero-image',
  '.aviation-service-hero-visual',
  '.global-service-hero-image',
  '.franchise-hero-image',
].join(',');

function canAnimate(el) {
  if (!el || el instanceof SVGElement) return false;
  if (el.matches('script, style, link, meta')) return false;
  if (el.matches(ENTRANCE_SELECTOR)) return false;
  if (el.classList.contains('reveal') || el.closest('.reveal')) return false;
  const position = window.getComputedStyle(el).position;
  if (position === 'sticky' || position === 'fixed') return false;
  return true;
}

function isBelowFold(el) {
  return el.getBoundingClientRect().top >= window.innerHeight;
}

function splitHeading(heading) {
  if (heading.dataset.motionWords === 'true') return [];
  const walker = document.createTreeWalker(heading, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => {
    const text = node.nodeValue;
    if (!text || !text.trim()) return;
    const fragment = document.createDocumentFragment();
    text.split(/(\s+)/).forEach((part) => {
      if (!part) return;
      if (/^\s+$/.test(part)) {
        fragment.appendChild(document.createTextNode(' '));
        return;
      }
      const word = document.createElement('span');
      word.className = 'motion-word';
      word.textContent = part;
      fragment.appendChild(word);
    });
    node.parentNode.replaceChild(fragment, node);
  });
  heading.dataset.motionWords = 'true';
  return Array.from(heading.querySelectorAll('.motion-word'));
}

export default function SiteMotion() {
  const pathname = usePathname();

  useEffect(() => {
    if (typeof window === 'undefined' || !('IntersectionObserver' in window)) return undefined;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return undefined;
    if (typeof Element.prototype.animate !== 'function') return undefined;

    const seen = new Set();
    const hidden = [];

    const register = (el, index) => {
      if (seen.has(el) || !canAnimate(el) || !isBelowFold(el)) return;
      seen.add(el);
      el.style.opacity = '0';
      hidden.push([el, index]);
    };

    const cards = document.querySelectorAll(CARD_SELECTOR);
    cards.forEach((el) => {
      const index = Array.prototype.indexOf.call(el.parentElement.children, el);
      register(el, index);
    });

    const blocks = document.querySelectorAll('main section > *');
    blocks.forEach((el) => {
      if (el.matches(CARD_SELECTOR) || el.querySelector(CARD_SELECTOR)) return;
      register(el, 0);
    });

    const wordHeadings = [];
    document.querySelectorAll('main h2').forEach((heading) => {
      if (!isBelowFold(heading)) return;
      const words = splitHeading(heading);
      if (words.length) wordHeadings.push([heading, words]);
    });

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        const record = hidden.find(([el]) => el === entry.target);
        if (record) {
          const delay = Math.min(record[1], 6) * 55;
          const animation = entry.target.animate(
            [
              { opacity: 0, transform: 'translateY(18px)' },
              { opacity: 1, transform: 'translateY(0)' },
            ],
            { duration: 620, delay, easing: EASE, fill: 'backwards' },
          );
          animation.onfinish = () => {
            entry.target.style.opacity = '';
          };
        }
        const headingRecord = wordHeadings.find(([el]) => el === entry.target);
        if (headingRecord) {
          headingRecord[1].forEach((word, index) => {
            word.animate(
              [
                { opacity: 0, transform: 'translateY(0.45em)' },
                { opacity: 1, transform: 'translateY(0)' },
              ],
              { duration: 520, delay: Math.min(index, 8) * 32, easing: EASE, fill: 'backwards' },
            );
          });
        }
        observer.unobserve(entry.target);
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -30px 0px' });

    hidden.forEach(([el]) => observer.observe(el));
    wordHeadings.forEach(([heading]) => observer.observe(heading));

    const onScroll = () => {
      document.documentElement.classList.toggle('is-scrolled', window.scrollY > 10);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });

    return () => {
      observer.disconnect();
      hidden.forEach(([el]) => { el.style.opacity = ''; });
      window.removeEventListener('scroll', onScroll);
      document.documentElement.classList.remove('is-scrolled');
    };
  }, [pathname]);

  return null;
}
